<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Rest;

use DateInterval;
use DateTimeImmutable;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Application\TokenGranter\TokenGranterMediator;
use Civi\Lughauth\Features\Oidc\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\Oidc\Key\Domain\Gateway\TokenSigner;
use Civi\Lughauth\Features\Oidc\Session\Domain\Gateway\TemporalKeysGateway;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\OAuthTokenException;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ValueObject\PkceChallenge;
use Civi\Lughauth\Features\Oidc\Device\Application\DeviceAuthorizationService;
use Civi\Lughauth\Features\Oidc\Device\Domain\Exception\DeviceAuthorizationException;

class TokenController
{
    public function __construct(
        private readonly Context $context,
        private readonly TokenGranterMediator $granter,
        private readonly ClientStoreGateway $clientDataGateway,
        private readonly TemporalKeysGateway $temporals,
        private readonly TokenSigner $manager
    ) {
    }

    public function post(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        try {
            return $this->handlePost($request, $response, $args);
        } catch (OAuthTokenException $ex) {
            $payload = ['error' => $ex->error(), 'error_description' => $ex->getMessage()];
            $encoded = json_encode($payload);
            $response->getBody()->write($encoded !== false ? $encoded : '{}');
            return $response->withStatus($ex->statusCode())->withHeader('Content-Type', 'application/json');
        }
    }

    private function handlePost(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $params = (array) ($request->getParsedBody() ?? []);
        // Get client data
        $grant = $params['grant_type'] ?? '';
        $scopes = $params['scope'] ?? '';
        if ("authorization_code" == $grant) {
            $code = $this->temporals->retrieveTemporalAuthCode($params['code'] ?? '');
            if (!$code) {
                throw new UnauthorizedException("Unkonw code");
            }
            if ($code->codeChallenge !== null) {
                $codeVerifier = $params['code_verifier'] ?? null;
                if ($codeVerifier === null || $codeVerifier === '') {
                    throw OAuthTokenException::invalidRequest('code_verifier is required');
                }
                $pkce = PkceChallenge::fromRequest($code->codeChallenge, $code->codeChallengeMethod);
                if ($pkce === null || !$pkce->verify((string) $codeVerifier)) {
                    throw OAuthTokenException::invalidGrant('code_verifier does not match code_challenge');
                }
            }
            $client = $code->client;
            $auth = $code->data;
            $identity = ['nonce' => $code->nonce ];
            $scopes = $code->request->scope;
        } elseif ("refresh_token" == $grant) {
            $refreshPayload = $this->manager->verifyTokenPayload($tenant, $params['refresh_token'] ?? '');
            if ($refreshPayload === null) {
                throw new UnauthorizedException("Invalid refresh token");
            }
            $originalScope = $refreshPayload['original_scope'] ?? '';
            $scopes = $params['scope'] ?? $originalScope;
            $audiences = isset($params['audience']) ? explode(",", $params['audience']) : [];
            $client = $this->clientDataGateway->preValidatedClient($params['client_id']);
            if (!$client) {
                throw new UnauthorizedException("Unknown client");
            }
            $auth = $this->granter->authenticate(
                $grant,
                $tenant,
                new AuthenticationRequest($client, $originalScope, "", null, [$client->id, ...$audiences]),
                $params
            );
            $identity = [];
        } elseif (DeviceAuthorizationService::grantType() == $grant) {
            try {
                $client = null;
                if (isset($_SERVER['PHP_AUTH_USER']) && isset($_SERVER['PHP_AUTH_PW'])) {
                    $client = $this->clientDataGateway->clientData($_SERVER['PHP_AUTH_USER'], $_SERVER['PHP_AUTH_PW']);
                } else {
                    $clientId = (string) ($params['client_id'] ?? '');
                    if ($clientId !== '') {
                        $client = $this->clientDataGateway->preValidatedClient($clientId);
                    }
                }
                if (!$client) {
                    throw DeviceAuthorizationException::invalidClient();
                }
                if (false === array_search($grant, $client->grants)) {
                    throw DeviceAuthorizationException::invalidClient();
                }
                $audiences = isset($params['audience']) ? explode(",", $params['audience']) : [];
                $auth = $this->granter->authenticate(
                    $grant,
                    $tenant,
                    new AuthenticationRequest($client, "", "", null, [$client->id, ...$audiences]),
                    $params
                );
                $identity = [];
            } catch (DeviceAuthorizationException $ex) {
                return $this->deviceErrorResponse($ex, $response);
            }
        } else {
            if (!isset($_SERVER['PHP_AUTH_USER']) || !isset($_SERVER['PHP_AUTH_PW'])) {
                throw new UnauthorizedException(message: 'Unauthorized by header.');
            }
            $client = $this->clientDataGateway->clientData($_SERVER['PHP_AUTH_USER'], $_SERVER['PHP_AUTH_PW']);
            if (!$client) {
                throw new UnauthorizedException(message: 'Unauthorized.');
            }
            if (false === array_search($grant, $client->grants)) {
                throw new UnauthorizedException(message: 'Unauthorized.');
            }
            $audiences = isset($params['audience']) ? explode(",", $params['audience']) : [];
            $auth = $this->granter->authenticate(
                $grant,
                $tenant,
                new AuthenticationRequest($client, "", "", null, [$client->id, ...$audiences]),
                $params
            );
            $identity = [];
        }
        if ($auth === null || !$auth->valid) {
            throw new UnauthorizedException("No auth");
        }
        $issuer = $this->context->getBaseUrl().'/oauth/openid/'. $tenant;
        $detail = [
            'aud' => $this->tokenAudiences($client->id, $auth->audiences ?? []),
            'azp' => $client->id,
            'iss' => $issuer,
            'sub' => $auth->id,
            'tenant' => $auth->tenant,
            'scope' => $auth->scope ?? '',
            'roles' => $auth->roles ?? [],
            'groups' => $auth->groups ?? []
        ];
        $scopesForClaims = $auth->scope ?? $scopes;
        if (str_contains($scopesForClaims, 'profile')) {
            $detail['name'] = $auth->name ?? '';
        }
        if (str_contains($scopesForClaims, 'email')) {
            $detail['email'] = $auth->email ?? '';
        }
        $identity = [...$detail, ...$identity];
        $expiration = new DateInterval("PT10M");
        $now = new DateTimeImmutable();
        $expires = $now->add($expiration);
        $data = [
            'token_type' => 'Bearer',
            'expires_in' => $expires->getTimestamp() - $now->getTimestamp(),
            'id_token' => $this->manager->sign($tenant, $identity, $expiration),
            'access_token' => $this->manager->sign($tenant, array_merge($detail, [
                // https://www.iana.org/assignments/jwt/jwt.xhtml
                'scope' => $auth->scope ?? '',
                'roles' => $auth->roles ?? [],
                'groups' => $auth->groups ?? []
            ]), $expiration),
        ];
        $data['refresh_token'] = $this->manager->sign($tenant, ['keypass' => $auth->id, 'azp' => $client->id, 'scope' => ['refresh'], 'original_scope' => $auth->scope ?? '' ], new DateInterval("PT10H"));
        $encoded = json_encode($data);
        $response->getBody()->write($encoded !== false ? $encoded : '{}');
        return $response->withHeader('Content-Type', 'application/json');
    }

    private function tokenAudiences(string $clientId, ?array $audiences): string|array
    {
        $aud = array_values(array_unique([$clientId, ...($audiences ?? [])]));
        return count($aud) == 1 ? $aud[0] : $aud;
    }

    private function deviceErrorResponse(DeviceAuthorizationException $exception, ResponseInterface $response): ResponseInterface
    {
        $payload = [
            'error' => $exception->error(),
            'error_description' => $exception->getMessage()
        ];
        $encoded = json_encode($payload);
        $response->getBody()->write($encoded !== false ? $encoded : '{}');
        return $response
            ->withStatus($exception->statusCode())
            ->withHeader('Content-Type', 'application/json');
    }
}
